// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup: fund Alice with 1 ether, Bob with 0
        address alice = address(0x1234);
        address bob = address(0x5678);
        vm.deal(alice, 1 ether);
        vm.deal(bob, 0);

        // Alice deposits 1 ether
        vm.prank(alice);
        c.addToBalance{value: 1 ether}();

        // Bob calls addToBalance with 0 value (does nothing on balance, but sets msg.value = 0)
        vm.prank(bob);
        c.addToBalance{value: 0}();

        // Now Alice deposits 1 more ether; on reference balance becomes 2, on bug it becomes 0 - 0 (no change because msg.value was 0 on bob's call? Wait, bug affects the caller's own balance.)
        // Actually the bug is in addToBalance: it subtracts msg.value from userBalance[msg.sender].
        // For Bob's call with 0 value, no change. For Alice's second call with 1 ether, reference adds 1 (becomes 2), bug subtracts 1 (becomes 0) - but require check passes because (userBalance + msg.value) >= userBalance holds (0+1 >= 0). No revert, but balance changes direction.
        // To force a revert in bug, we need a scenario where subtraction causes underflow. Let's instead: after Bob's call, Alice calls with a large value that would cause underflow if subtracted.
        // Simpler: Alice deposits 1 wei, then calls addToBalance with 2 wei. Reference: 1+2=3. Bug: 1-2 = underflow (because userBalance is uint). The require check (1+2 >=1) passes, but subsequent -= reverts. So we can observe revert vs no revert.

        // Reset: fresh contract
        // Actually we need to redeploy for clean state — do it in setUp? No, we can just use new C() in test? But setUp already deploys. Let's just deploy another instance here?
        // Better: reuse existing c by resetting state manually? Not possible. We'll redeploy in test.
        C fresh = new C();
        address alice2 = address(0xdead);
        vm.deal(alice2, 1 ether);

        // Alice deposits 1 wei
        vm.prank(alice2);
        fresh.addToBalance{value: 1}();

        // Now Alice tries to add 2 wei; reference succeeds, bug reverts
        bool ok;
        try fresh.addToBalance{value: 2}() { ok = true; } catch { ok = false; }

        assertTrue(ok); // Reference: ok == true; Bug: ok == false
    }
}

